<?php require_once __DIR__.'/config/config.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$u=trim($_POST['username']);$p=$_POST['password'];if(strlen($p)<12)$msg='Use at least 12 characters.';else{$s=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);$msg='Admin created. Delete setup_admin.php now.';}}?><form method="post" style="max-width:400px;margin:60px auto;font:16px Arial"><?=csrf_field()?><h2>Create first admin</h2><input name="username" placeholder="Username" required><p><input type="password" name="password" placeholder="Password (12+ chars)" required></p><button>Create admin</button><p><?=e($msg)?></p></form>